python3 -c "
import csv
import math

def calculate_skewness(data):
    n = len(data)
    if n < 3:
        return 0.0

    mean = sum(data) / n

    m2 = sum((x - mean) ** 2 for x in data) / n
    m3 = sum((x - mean) ** 3 for x in data) / n

    if m2 == 0:
        return 0.0

    return m3 / (m2 ** 1.5)

prices = []
with open('data/housing_data.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        try:
            prices.append(float(row['price']))
        except ValueError:
            continue

if prices:
    skewness = calculate_skewness(prices)
    print(f'Skewness: {skewness}')
else:
    print('No data found')
"
